#include <stdint.h>

static const float MAX_STIRLING = 26.77f;

/* Begin auto-generated functions. The following functions are auto-generated. Do not edit directly. */

// BEGIN: poly_s

/**
* Evaluates a polynomial.
*
* ## Notes
*
* -   The implementation uses [Horner's rule][horners-method] for efficient computation.
*
* [horners-method]: https://en.wikipedia.org/wiki/Horner%27s_method
*
* @param x    value at which to evaluate the polynomial
* @return     evaluated polynomial
*/
static float poly_s( const float x ) {
	return 0.08333331788340907f + (x * (0.00347325578615491f + (x * -0.002705194986674176f)));
}

// END: poly_s

// BEGIN: poly_p

/**
* Evaluates a polynomial.
*
* ## Notes
*
* -   The implementation uses [Horner's rule][horners-method] for efficient computation.
*
* [horners-method]: https://en.wikipedia.org/wiki/Horner%27s_method
*
* @param x    value at which to evaluate the polynomial
* @return     evaluated polynomial
*/
static float poly_p( const float x ) {
	return 0.9999999822945073f + (x * (0.4227867745131584f + (x * (0.4117857447645796f + (x * (0.08203960091619193f + (x * (0.07232307985516519f + (x * (0.004130370201859976f + (x * (0.005397581592950993f + (x * 0.001536830450601906f)))))))))))));
}

// END: poly_p

/* End auto-generated functions. */

/**
* Evaluates the gamma function using Stirling's formula. The polynomial is valid for \\(33 \leq x \leq 172\\).
*
* @param x    input value
* @return     function value
*/
static float stirlingApprox( const float x ) {
	float w;
	float y;
	float v;

	w = 1.0f / x;
	w = 1.0f + ( w * poly_s( w ) );
	y = (float)stdlib_base_exp( -x );

	// Check `x` to avoid `pow()` overflow...
	if ( x > MAX_STIRLING ) {
		v = stdlib_base_powf( x, ( 0.5f * x ) - 0.25f );
		y *= v;
		y *= v;
	} else {
		y = stdlib_base_powf( x, x - 0.5f ) * y;
	}
	return STDLIB_CONSTANT_FLOAT32_SQRT_TWO_PI * y * w;
}

/**
* Evaluates the gamma function using a small-value approximation.
*
* @param x    input value
* @param z    scale factor
* @return     function value
*/
static float smallApprox( const float x, const float z ) {
	return z / ( ( 1.0f + ( STDLIB_CONSTANT_FLOAT32_EULERGAMMA * x ) ) * x );
}

/**
* Evaluates the gamma function of a single-precision floating-point number.
*
* ## Method
*
* 1.  Arguments between 0 and 10 are reduced by recurrence and the function is approximated by a polynomial function covering the interval (2,3)
* 2.  Large arguments are handled by Stirling's formula.
* 3.  Negative arguments are made positive using a reflection formula.
*
* ## Notes
*
* -   Relative error:
*
*     | arithmetic | domain    | # trials | peak    | rms     |
*     |:----------:|:---------:|:--------:|:-------:|:-------:|
*     | IEEE       | 0,-33     | 100,000  | 5.7e-7  | 1.0e-7  |
*     | IEEE       | -33,0     | 100,000  | 6.1e-7  | 1.2e-7  |
*
* @param x    input value
* @return     function value
*
* @example
* float v = stdlib_base_gammaf( 4.0f );
* // returns 6.0
*/
float stdlib_base_gammaf( const float x ) {
	bool direction;
	bool negative;
	bool small;
	float sign;
	float nz;
	int32_t i;
	float q;
	float p;
	float z;
	float xc;

	negative = 0;
	xc = x;

	if ( ( stdlib_base_is_integerf( x ) && x < 0 ) || stdlib_base_is_nanf( x ) || x == STDLIB_CONSTANT_FLOAT32_NINF ) {
		return 0.0f / 0.0f; //NaN
	}

	if ( x == 0.0f ) {
		if ( stdlib_base_is_negative_zerof( x ) ) {
			return STDLIB_CONSTANT_FLOAT32_NINF;
		}
		return STDLIB_CONSTANT_FLOAT32_PINF;
	}

	if ( x > 34.84425627277176174f ) {
		return STDLIB_CONSTANT_FLOAT32_PINF;
	}

	if ( x < -34.1955451965332f ) {
		return 0.0f;
	}

	if ( xc < 0.0f ) {
		negative = 1;
		q = -xc;
		p = stdlib_base_floorf( q );
		if ( p == q ) {
			return 0.0f / 0.0f;
		}
		i = (int32_t)p;
		if ( ( i & 1 ) == 0 ) {
			sign = -1.0f;
		} else {
			sign = 1.0f;
		}
		nz = q - p;
		if ( nz > 0.5f ) {
			p += 1.0f;
			nz = q - p;
		}
		nz = q * stdlib_base_sinf( STDLIB_CONSTANT_FLOAT32_PI * nz );
		if ( nz == 0.0f ) {
			return 0.0f / 0.0f;
		}
		if ( nz < 0.0f ) {
			nz = -nz;
		}
		xc = q;
	}
	// if ( xc >= 10.0f ) {
	// 	z = stirlingApprox( xc );
	// }
	if ( xc < 2.0f ) {
		direction = 1;
	} else {
		direction = 0;
	}
	z = 1.0f;
	while ( xc >= 3.0f ) {
		xc -= 1.0f;
		z *= xc;
	}
	small = 0;
	while ( xc < 2.0f ) {
		if ( xc < 1.0e-4f ) {
			small = 1;
			break;
		}
		z *= xc;
		xc += 1.0f;
	}

	if ( small ) {
		if ( xc == 0.0f ) {
			return STDLIB_CONSTANT_FLOAT32_PINF;
		}
		p = smallApprox( xc, z );
	} else {
		if ( direction ) {
			z = 1.0f / z;
		}
		if ( xc == 2.0f ) {
			p = z;
		} else {
			xc -= 2.0f;
			p = z * poly_p( xc );
		}
	}

	if ( negative ) {
		p = sign * STDLIB_CONSTANT_FLOAT32_PI / ( nz * p );
	}
	return p;
}
